// Attic/loft cross-section illustration, one per market.
// The images are generated by `npm run images` (scripts/make-images.ts) into public/images/
// and committed. Edit the labels here, then rerun the script.
import type { MarketId } from "@/engine/types";
import type { Group } from "@/routes/registry";

export interface AtticDiagram {
  /** file in public/images/, keyword-rich in the market's language */
  file: string;
  title: string;
  subtitle: string;
  labels: {
    add: [string, string];
    existing: [string, string];
    joists: string;
    ceiling: string;
    attic: string;
    room: string;
    measure: string;
  };
  /** depth callouts: layer to add, existing layer */
  dims: { add: string; existing: string };
  alt: string;
  caption: string;
}

export const DIAGRAM_SIZE = { width: 1200, height: 700 } as const;

/** Pages that show the attic diagram. */
export const ATTIC_DIAGRAM_GROUPS: Group[] = ["home", "attic", "blown", "thickness"];

